// Host dependencies of the 2.42304.0 Code landing texture (src/generated/landing-texture/**, generated by
// scripts/extract-landing-texture.mjs). Only runtime services the official bundle reads from its own shell are supplied
// here; the layer, its shaders, timing, preference store and every class string stay original. Nothing here draws.
import { useReducedMotion } from './use-reduced-motion.js';

// shared-frame `mu` (Ya): Ji(useContext(Oa)), the owner window of the overlay-host context, which falls back to
// globalThis.window when no provider is mounted. Each local window is its own renderer and nothing provides that
// context, so the official fallback is the whole answer; during SSR there is no window and the reveal never starts.
export function useOwnerWindow() {
  return globalThis.window;
}

// shared-156 `Ic` (fE): { mode, setMode, shouldReduceMotion: mode === 'reduce' || prefers-reduced-motion }. The local
// counterpart of `appearance:reduceMotion` is prefs.motion, which appearance-root.mjs writes as
// html[data-reduce-motion="true"] (the attribute the official mE() writes); use-reduced-motion.js reads it and the media
// query live. The setter belongs to Settings › Appearance and is not needed by the texture.
export function useReduceMotion() {
  return { shouldReduceMotion: useReducedMotion() };
}

// shared-25 `$h` (ls): tags lazy imports with a chunk-load telemetry origin ("background" / "code_landing_texture").
// Telemetry only, no UI effect; not migrated.
export function withChunkLoadContext(_context, load) {
  return load();
}

// cc43287c9 `__vite__mapDeps` and the Vite preload helper `l`: the official bundle links a lazy chunk's stylesheets
// before importing it. The texture chunk's only dependency, shared-frame-CegduNQ2.css, is linked by index.html, and the
// local bundler preloads its own chunks, so the import runs directly.
export function chunkDependencies() {
  return [];
}
export function preloadChunk(load) {
  return load();
}
